import{d as c,C as t,o as b,c as g,j as a,a as s,E as o,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四十五章","description":"从大成若缺、大盈若冲到清静为正，并列说明本站正文与王注所据句式的差异。","frontmatter":{"title":"道德经第四十五章","description":"从大成若缺、大盈若冲到清静为正，并列说明本站正文与王注所据句式的差异。","category":"guide","aliases":["道德经第四十五章","老子第四十五章","dao de jing chapter 45"],"source":["王弼《道德真经注》卷三"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-45.md","filePath":"daoism/dao-de-jing/chapter-45.md","lastUpdated":1794189804000}'),u={name:"daoism/dao-de-jing/chapter-45.md"},q=c({...u,setup(p){const r=[{id:"completion-without-fixed-form",label:"大成若缺",showLabel:!0,sentences:[["大成若缺，其用不",{text:"弊",glossary:"bi"},"。"]],note:["【白话】至大的成就看似仍有欠缺，但它的功用并不衰败。依王弼，它随事物而成，不把某一个完成的形象固定为唯一标准。","【王弼注择要】「随物而成，不为一象，故若缺也。」注以成物而不固守一象解释若缺，并非说任何欠缺都值得赞赏。","【读法】弊取敝坏、衰竭义；成与用要连读，判断不只看外观是否完整，也看能否持续成全具体事物。"]},{id:"fullness-with-openness",label:"大盈若冲",showLabel:!0,sentences:[["大",{text:"盈",glossary:"ying"},"若",{text:"冲",glossary:"chong"},"，其用不穷。"]],note:["【白话】至大的充盈看似空虚，功用却不穷尽。它虽充足，却不执藏、自矜，所以能随事物的需要而兴起作用。","【王弼注择要】「大盈充足，随物而兴，无所爱矜，故若冲也。」冲为虚，而不是匮乏；王注以不执爱自矜说明其开放。","【读法】可连第四章道冲而用之或不盈理解。本句不是取消充足与不足的实际差别，而是反省充足是否反成封闭。"]},{id:"straightness-skill-and-speech",label:"大直若屈",showLabel:!0,sentences:[["大直若",{text:"屈",glossary:"qu"},"，大巧若",{text:"拙",glossary:"zhuo"},"，大辩若",{text:"讷",glossary:"ne"},"。"]],note:["【白话】至大的正直看似有所弯曲，至大的巧能看似笨拙，至善的言辩看似言语迟缓。它们因事成用，不以整齐划一、炫巧或口舌敏捷来显示自己。","【王弼注择要】「随物而直，直不在一，故若屈也。」大巧的注为「因自然以成器，不造为异端」；大辩的注为「因物而言，己无所造」，分别说明不固一法、不刻意造异与不凭己意造说。","【读法】屈在这里是弯曲，与第五章虚而不屈的穷尽义分开。拙、讷都在若字之后，不能以此赞美欠缺能力、拒绝表达或言语障碍本身。"]},{id:"two-readings-of-cold-and-heat",label:"静胜躁，寒胜热",showLabel:!0,sentences:[[{text:"静",glossary:"jing"},"胜",{text:"躁",glossary:"zao"},"，寒胜热。"]],note:["【白话】按本站现文：安静能克服躁动，寒冷能胜过炎热。两句分别用静躁、寒热构成对照。","【校读】所据电子录文作「躁胜寒，静胜热」，与本站静胜躁、寒胜热不是同一句式。依录文则可译为：活动能抵御寒冷，安静能胜过暑热。本站先保留现文，两种句式分列，不混作一译。","【王弼注择要】「躁罢然后胜寒，静无为以胜热。」此注循录文躁胜寒、静胜热而发，以活动至劳罢才胜寒、静而无为以胜热作比较；不能拿它逐字证明本站的静胜躁、寒胜热。","【读法】躁罢的罢循疲罢来理解。这里是动静与寒热的取象，不据此给出医学或具体防寒降温处方。"]},{id:"clarity-and-stillness-as-standard",label:"清静为天下正",showLabel:!0,sentences:[[{text:"清静",glossary:"qingjing"},"为天下",{text:"正",glossary:"zheng"},"。"]],note:["【白话】清明安静、不妄扰事物，可以成为天下的准则。依王弼，清静使事物保全其真实，才贯通前面若缺、若冲等不固一形的成用。","【王弼注择要】「静则全物之真，躁则犯物之性。」注又说「故唯清静，乃得如上诸大也」，回扣大成、大盈、大直等诸句。","【读法】正取准则义，清静不等于一切场合都停止行动；其着眼点是少以己意侵扰、让事物得以成全。这里的古注承接的是所据录文的动静寒热句式，与上一段本站现文的差异须保留。"]}],n=[{id:"bi",term:"弊",sense:2},{id:"ying",term:"盈",sense:1},{id:"chong",term:"冲",sense:1},{id:"qu",term:"屈",sense:2},{id:"zhuo",term:"拙",sense:1},{id:"ne",term:"讷",sense:1},{id:"jing",term:"静",sense:1},{id:"zao",term:"躁",sense:1},{id:"qingjing",term:"清静",sense:1},{id:"zheng",term:"正",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return b(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四十五章",tabindex:"-1"},[s("道德经第四十五章 "),a("a",{class:"header-anchor",href:"#道德经第四十五章","aria-label":'Permalink to "道德经第四十五章"'},"​")],-1)),o(i,{title:"大成为何若缺，清静怎样成全万物",summary:"本章用若缺、若冲、若屈、若拙与若讷写不固守外观的成用。王弼以随物、因自然来解释，最后归于清静。本站静胜躁、寒胜热与所据录文不同，阅读时须分开辨认。",points:[{label:"先读",text:"若缺与若冲写不固一相、不自满，不是赞美不能发挥作用的缺陷。"},{label:"再辨",text:"大直、大巧、大辩随物成用，不靠刻意制造姿态显示高明。"},{label:"后看",text:"本站静胜躁、寒胜热先按现文翻译，王注另循躁胜寒、静胜热解释。"}],hint:"屈读 qū，拙读 zhuō，讷读 nè，弊读 bì；本页保留原文，并在段释义与校读说明列出重要差异。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[s("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:r,glossary:n}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[s("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"大成若缺，其用不弊。",tone:"不以一象限成就",guide:"随物而成仍能起用，若缺不是放弃完成事情。"},{text:"大直若屈，大巧若拙，大辩若讷。",tone:"因物成用的尺度",guide:"不固执同一形式，也不靠造异与炫辩显示自己。"},{text:"清静为天下正。",tone:"回到全物之真",guide:"少以躁动侵扰物性，并记住本站前句与王注录文的差异。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[s("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:n}),e[4]||(e[4]=m("",15))])}}});export{_ as __pageData,q as default};
